#!/usr/bin/env node
/**
 * Generate the pgTAP half of the contact-info parity check.
 *
 * `public.contains_contact_info()` and its TypeScript twin in src/lib/contact-info.ts must agree.
 * Both are tested against src/lib/__fixtures__/contact-info-cases.json — Vitest reads it
 * directly, and this turns it into SQL.
 *
 * The generated file is committed so `supabase test db` needs no build step. Run with --check in
 * CI to fail if somebody edited the fixtures without regenerating, which would otherwise leave
 * the database side silently testing an older set of cases than the TypeScript side.
 *
 *   node scripts/gen-contact-info-parity.mjs
 *   node scripts/gen-contact-info-parity.mjs --check
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const fixtures = join(root, "src/lib/__fixtures__/contact-info-cases.json");
const target = join(root, "supabase/tests/contact_info_parity_test.sql");

const cases = JSON.parse(readFileSync(fixtures, "utf8"));

// Postgres string literals: double any single quote.
const lit = (s) => `'${String(s).replace(/'/g, "''")}'`;

const lines = [
  "-- Winch Up :: contact-info parity",
  "--",
  "-- GENERATED by scripts/gen-contact-info-parity.mjs from",
  "-- src/lib/__fixtures__/contact-info-cases.json. Do not edit by hand: edit the fixtures and",
  "-- regenerate, or the two implementations stop being tested against the same cases.",
  "--",
  "-- public.contains_contact_info() has a TypeScript twin in src/lib/contact-info.ts. The database",
  "-- is the enforcement point; the twin exists so somebody typing their phone number into a public",
  "-- field finds out while typing rather than losing the form on submit. That only helps if they",
  "-- agree, and this is what makes them agree.",
  "",
  "begin;",
  "",
  "create extension if not exists pgtap with schema extensions;",
  "set search_path = public, extensions;",
  "",
  "select no_plan();",
  "",
  "-- ---------------------------------------------------------------------------",
  "-- Blocked: these must be rejected from any public free-text field",
  "-- ---------------------------------------------------------------------------",
  "",
];

for (const { text, why } of cases.blocked) {
  lines.push(
    `select ok(public.contains_contact_info(${lit(text)}),`,
    `  ${lit(`blocks — ${why}`)});`,
  );
}

lines.push(
  "",
  "-- ---------------------------------------------------------------------------",
  "-- Allowed: ordinary description a stuck driver would actually type",
  "-- ---------------------------------------------------------------------------",
  "",
);

for (const { text, why } of cases.allowed) {
  lines.push(
    `select ok(not public.contains_contact_info(${lit(text)}),`,
    `  ${lit(`allows — ${why}`)});`,
  );
}

lines.push(
  "",
  "select ok(not public.contains_contact_info(null), 'null is treated as clean');",
  "",
  "select * from finish();",
  "rollback;",
  "",
);

const out = lines.join("\n");

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(target, "utf8");
  } catch {
    console.error("contact-info parity: generated test is missing. Run:");
    console.error("  node scripts/gen-contact-info-parity.mjs");
    process.exit(1);
  }
  if (current.replace(/\r\n/g, "\n") !== out) {
    console.error("contact-info parity: fixtures changed but the generated test was not updated.");
    console.error("Run: node scripts/gen-contact-info-parity.mjs");
    process.exit(1);
  }
  console.log(
    `contact-info parity: generated test is current (${cases.blocked.length} blocked, ${cases.allowed.length} allowed).`,
  );
} else {
  writeFileSync(target, out);
  console.log(
    `contact-info parity: wrote ${target} (${cases.blocked.length} blocked, ${cases.allowed.length} allowed).`,
  );
}
